Definition ch_arm12_1RB0LD_1RC1RA_1LA1RA_0RB1LD : list rstep := [RB (SWin 4)].
Lemma ok_arm12_1RB0LD_1RC1RA_1LA1RA_0RB1LD :
  check_arm tm true true rules arm12_1RB0LD_1RC1RA_1LA1RA_0RB1LD ch_arm12_1RB0LD_1RC1RA_1LA1RA_0RB1LD = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm12_1RB0LD_1RC1RA_1LA1RA_0RB1LD : RuleSound tm true true arm12_1RB0LD_1RC1RA_1LA1RA_0RB1LD.
Proof. eapply arm_sound; [exact rules_sound_1RB0LD_1RC1RA_1LA1RA_0RB1LD | exact ok_arm12_1RB0LD_1RC1RA_1LA1RA_0RB1LD]. Qed.

