(** ** What this board establishes

    49 of 49 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt], at [(Gray, 2)]

    The arms below are the case split of [LadderCheck.gray_split], built from
    the FAMILY rather than mined: one interior arm per CLASS (there are four,
    LADDER_PLAN 4i) and per arm index, and one fill arm per WIDTH index.
    Every certificate arm above is one of these with its run lengths pinned to
    their lower bounds, which is why 49 of them collapse to 5 here.

    The family's parity is 0.  That is not a choice: it is the digit sum
    of the boot, it is the value's low bit, [+2] preserves it, and it is what
    makes "member of this width" a predicate rather than "every string of this
    width".  The four classes and the top's shape are read off it.

    The interior class runs at threshold 0 stride 1, the fill
    class at threshold 2 stride 1.  [boardG_neverqh] consumes
    them, the boot, and one chain per state per fill arm. *)
Definition iarm0_0_1RB0RB_1LC1RD_0LC1LA_0RD0LA : LRule :=
  mkLRule (mkC StD (mkS [S0;S0] [S0] 1 0 []) S1 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S1;S1] [S0] 1 0 []) S1 (mkS [] [] 0 0 [])) 0 6.
Definition ch_iarm0_0_1RB0RB_1LC1RD_0LC1LA_0RD0LA : list rstep := [RB (SWin 6)].
Lemma ok_iarm0_0_1RB0RB_1LC1RD_0LC1LA_0RD0LA :
  check_arm tm false true rules iarm0_0_1RB0RB_1LC1RD_0LC1LA_0RD0LA
            ch_iarm0_0_1RB0RB_1LC1RD_0LC1LA_0RD0LA = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm1_0_1RB0RB_1LC1RD_0LC1LA_0RD0LA : LRule :=
  mkLRule (mkC StD (mkS [S0;S1] [S1] 1 0 []) S1 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S1;S0] [S1] 1 0 []) S1 (mkS [] [] 0 0 [])) 0 6.
Definition ch_iarm1_0_1RB0RB_1LC1RD_0LC1LA_0RD0LA : list rstep := [RB (SWin 6)].
Lemma ok_iarm1_0_1RB0RB_1LC1RD_0LC1LA_0RD0LA :
  check_arm tm false true rules iarm1_0_1RB0RB_1LC1RD_0LC1LA_0RD0LA
            ch_iarm1_0_1RB0RB_1LC1RD_0LC1LA_0RD0LA = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm2_0_1RB0RB_1LC1RD_0LC1LA_0RD0LA : LRule :=
  mkLRule (mkC StD (mkS [S1] [S0] 1 0 [S1;S0]) S1 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S0] [S0] 1 0 [S1;S1]) S1 (mkS [] [] 0 0 [])) 2 8.
Definition ch_iarm2_0_1RB0RB_1LC1RD_0LC1LA_0RD0LA : list rstep := [RB (SWin 3);RB (SCycL 1 0);RB (SWin 4);RB (SCycR 1);RB (SWin 1)].
Lemma ok_iarm2_0_1RB0RB_1LC1RD_0LC1LA_0RD0LA :
  check_arm tm false true rules iarm2_0_1RB0RB_1LC1RD_0LC1LA_0RD0LA
