  mkLRule (mkC StD (mkS [S1] [S0] 1 0 [S1]) S1 (mkS [] [] 0 0 []))
          (mkC StD (mkS [S0] [S0] 1 0 [S1;S1]) S1 (mkS [] [] 0 0 [])) 2 8.
Definition ch_farm2_1RB0RB_1LC1RD_0LC1LA_0RD0LA : list rstep := [RB (SWin 3);RB (SCycL 1 0);RB (SWin 1);RB (SWinL 3);RB (SCycR 1);RB (SWin 1)].
