Definition fm1_1RB0RC_0LB1LA_1LB1RD_1LC0RD (r : nat) : nat := match r with | 1 => 1 | _ => 0 end.
Definition fm2_1RB0RC_0LB1LA_1LB1RD_1LC0RD (r : nat) : nat := match r with | 1 => 1 | _ => 0 end.

(** One chain per state per fill arm.  [vis_of_run] turns each into a visit
    and [topsF_cofinal] says the tops keep coming, which is all the liveness
    needs. *)
Definition vis_1RB0RC_0LB1LA_1LB1RD_1LC0RD (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 1;SCycR 1;SWin 2;SWinR 4;SCycL 1 0;SWin 2]
  | 1, (StA, S1) => [SWin 1;SCycR 1;SWin 2;SWinR 4;SCycL 1 0;SWin 4]
  | 1, (StB, S0) => [SWin 1;SCycR 1;SWinR 5]
  | 1, (StB, S1) => [SWin 1;SCycR 1;SWin 2;SWinR 4;SCycL 1 0;SWin 1]
  | 1, (StC, S0) => [SWin 1;SCycR 1;SWinR 4]
  | 1, (StC, S1) => []
  | 1, (StD, S0) => [SWin 1;SCycR 1;SWinR 3]
  | 1, (StD, S1) => [SWin 1]
  | _, _ => []
  end.

