  i < 2 -> r < 1 + 1 ->
  RuleSound tm (negb (fm_left FAM)) (fm_left FAM) (iarm_1RB0RC_0LB1LA_1LB1RD_1LC0RD i r).
Proof.
  intros i r Hi Hr.
  destruct i as [|i].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0RC_0LB1LA_1LB1RD_1LC0RD | exact ok_iarm0_0_1RB0RC_0LB1LA_1LB1RD_1LC0RD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0RC_0LB1LA_1LB1RD_1LC0RD | exact ok_iarm0_1_1RB0RC_0LB1LA_1LB1RD_1LC0RD]. }
    exfalso; lia.
  }
  destruct i as [|i].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0RC_0LB1LA_1LB1RD_1LC0RD | exact ok_iarm1_0_1RB0RC_0LB1LA_1LB1RD_1LC0RD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB0RC_0LB1LA_1LB1RD_1LC0RD | exact ok_iarm1_1_1RB0RC_0LB1LA_1LB1RD_1LC0RD]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

