(** The machine-level theorem, at the INSTRUCTION level: the board runs on
    the machine wrapped at the pins and [LadderCheckFibTr.boardF_neverqhtr]
    turns it into [NeverQuasiHaltsTr] of the machine itself. *)
Theorem nqhtr_1RB0RC_0LB1LA_1LB1RD_1LC0RD : NeverQuasiHaltsTr tm_1RB0RC_0LB1LA_1LB1RD_1LC0RD.
Proof.
  eapply (boardF_neverqhtr tm_1RB0RC_0LB1LA_1LB1RD_1LC0RD pins_1RB0RC_0LB1LA_1LB1RD_1LC0RD FAM
                           iarm_1RB0RC_0LB1LA_1LB1RD_1LC0RD 1 1
                           farm_1RB0RC_0LB1LA_1LB1RD_1LC0RD 1 1
                           fw1_1RB0RC_0LB1LA_1LB1RD_1LC0RD fw2_1RB0RC_0LB1LA_1LB1RD_1LC0RD fm1_1RB0RC_0LB1LA_1LB1RD_1LC0RD fm2_1RB0RC_0LB1LA_1LB1RD_1LC0RD
                           vis_1RB0RC_0LB1LA_1LB1RD_1LC0RD [0]).
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - vm_compute; repeat constructor.
  - vm_compute; repeat constructor.
  - vm_compute; lia.
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - intros k Hk. apply (filled_fib0 FAM 0 k);
      vm_compute; reflexivity.
  - repeat constructor.
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - lia.
  - exact iarm_sound_1RB0RC_0LB1LA_1LB1RD_1LC0RD.
  - exact iarm_lhs_1RB0RC_0LB1LA_1LB1RD_1LC0RD.
  - exact iarm_rhs_1RB0RC_0LB1LA_1LB1RD_1LC0RD.
  - exact iarm_cb_1RB0RC_0LB1LA_1LB1RD_1LC0RD.
  - lia.
  - lia.
  - exact fw_1RB0RC_0LB1LA_1LB1RD_1LC0RD.
  - exact fm12_1RB0RC_0LB1LA_1LB1RD_1LC0RD.
  - exact farm_sound_1RB0RC_0LB1LA_1LB1RD_1LC0RD.
  - exact farm_lhs_1RB0RC_0LB1LA_1LB1RD_1LC0RD.
  - exact farm_rhs_1RB0RC_0LB1LA_1LB1RD_1LC0RD.
  - exact farm_cb_1RB0RC_0LB1LA_1LB1RD_1LC0RD.
  - exact vis_ok_1RB0RC_0LB1LA_1LB1RD_1LC0RD.
  - exact boot_1RB0RC_0LB1LA_1LB1RD_1LC0RD.
Qed.

